import { test, expect } from '@playwright/test';

// A transient confirmation toast/banner can vanish before this line runs.
// Warn instead of failing the whole test over UI that already did its job --
// a REAL problem still surfaces as the next real step failing for real.
async function softCheck(label: string, fn: () => Promise<void>): Promise<void> {
  try { await fn(); } catch { console.warn('[soft-check] not visible in time (continuing): ' + label); }
}

// --- TEST DATA (edit these values in one place) ---
const data = {
  step4: 'LI-Demo-Term-' + Date.now(),   // Fill: textbox "Name" -- unique per run so this is replayable
};

test('add a glossary term', async ({ page }) => {
  // Step 1: open the application
  await page.goto('https://edc.qa.securiti.xyz/glossary');

  // Step 2: Click button "Add"   [A role]
  await page.getByRole('button', { name: 'Add', exact: true }).click();

  // Step 3: Click menuitem "Add Term"   [A testid]
  await page.getByTestId('add-term-button').click();

  // Step 4: Type into textbox "Name"   [A label]
  await page.getByLabel('Name', { exact: true }).fill(data.step4);
  await expect(page.getByLabel('Name', { exact: true })).toHaveValue(data.step4);

  // Step 5: Click button "Create"   [A testid]
  await page.getByTestId('glossary-entity-modal-create-button').click();
  await softCheck('Updating...', () => expect(page.getByText('Updating...')).toBeVisible());   // observed on screen right after this step (info)
});
